-- For God so loved the world, that He gave His only begotten Son,
-- that all who believe in Him should not perish but have everlasting life.
-- — John 3:16

-- 1PETER - POR Combined
-- Generated: 2026-01-22T06:19:50.214Z

-- c004-v001: Cristo pois tendo-sofrido na-carne, também vós a mesma disposição armai-vos; porque o-que sofreu na-carne cessou do-pecado;
-- c004-v002: para o não-mais dos-homens nas-concupiscências, mas na-vontade de-Deus, o restante na carne viver tempo.
-- c004-v003: Pois-é-suficiente – o passado tempo para-ter a-vontade dos gentios realizado, tendo-andado em lascívias, concupiscências, bebedeiras, orgias, banquetes, e ilícitas idolatrias.
-- c004-v004: No-qual – estranham, não concorrendo vós, para a mesma de dissolução inundação, blasfemando,
-- c004-v005: os-quais darão conta ao-que prontamente está para-julgar vivos, e mortos.
-- c004-v006: Para isto pois, também a-mortos foi-pregado-o-evangelho, para-que sejam-julgados por-um-lado segundo homens na-carne; vivam porém segundo Deus no-espírito.
-- c004-v007: De-todas-as-coisas porém o fim se-aproximou. Sede-sóbrios pois, e vigiai para orações;
-- c004-v008: antes-de-tudo, – o para vós-mesmos amor intenso tendo, porque o-amor cobre multidão de-pecados;
-- c004-v009: hospitaleiros uns-para-os-outros, – sem murmúrio;
-- c004-v010: cada-um conforme recebeu dom, uns-aos-outros vós-mesmos o ministrando, como bons administradores da-multiforme graça de-Deus.
-- c004-v011: Se alguém fala, como oráculos de-Deus; se alguém serve, como de força que supre – Deus, para-que em tudo seja-glorificado – Deus por-meio-de Jesus Cristo, a-quem é a glória, e o domínio, pelos – séculos dos séculos. Amém.
-- c004-v012: Amados, não estranheis a em vós provação-de-fogo para provação a-vós acontecendo, como coisa-estranha a-vós acontecendo;
-- c004-v013: mas na-medida-em-que participais dos – de-Cristo sofrimentos, alegrai-vos, para-que também na a revelação da glória dele, vos-alegreis exultando.
-- c004-v014: Se sois-injuriados no nome de-Cristo, bem-aventurados; porque o da glória, e o de Deus, Espírito sobre vós repousa; <segundo por-um-lado eles é-blasfemado, segundo porém vós é-glorificado>.
-- c004-v015: Não pois alguém de-vós sofra como homicida, ou ladrão, ou malfeitor, ou como intrometido;
-- c004-v016: se porém como cristão, não se-envergonhe; glorifique porém a Deus neste – nome –.
-- c004-v017: Porque é-o tempo de começar o julgamento pela a casa de Deus; se porém primeiro por nós, qual o fim dos-que são-desobedientes ao de Deus evangelho?
-- c004-v018: E se o justo dificilmente é-salvo, o (porém) ímpio e pecador onde aparecerá?
-- c004-v019: De-modo-que também, os-que sofrem segundo a vontade de Deus, ao-fiel Criador entreguem as almas deles em fazer-o-bem.

